#!/usr/bin/env python3

from pathlib import Path

import numpy as np
import pandas as pd
from scipy.stats import spearmanr, pearsonr, wilcoxon


ROOT = Path(__file__).resolve().parents[1]

R = (
    ROOT
    / "diagnostics/results/"
      "framewise_acc_pa_5task_current10457"
)

TASKS = [
    "task-0000",
    "task-0001",
    "task-0006",
    "task-0008",
    "task-0010",
]


# ============================================================
# Load raw frame/object rows generated by GPU jobs
# ============================================================

dfs = []

for task in TASKS:

    p = R / task / "framewise_acc_pa.csv"

    if not p.exists():
        raise FileNotFoundError(p)

    d = pd.read_csv(p)

    dfs.append(d)


raw = pd.concat(
    dfs,
    ignore_index=True,
)

raw = raw[
    np.isfinite(raw["local_acc_mps2"])
    & np.isfinite(raw["pa_mpjpe_mm"])
].copy()

raw.to_csv(
    R / "combined_raw_frame_object_rows.csv",
    index=False,
)


# ============================================================
# IMPORTANT:
#
# One clip can contain multiple rigid objects.
# We do NOT want to count the same Action acceleration several
# times just because the scene contains several objects.
#
# Therefore:
#   one clip + one frame -> one PA value
#
# by taking median PA across eligible rigid objects.
# ============================================================

frame = (
    raw
    .groupby(
        [
            "task",
            "clip",
            "frame",
        ],
        as_index=False,
    )
    .agg(
        local_acc_mps2=(
            "local_acc_mps2",
            "first",
        ),
        pa_mpjpe_mm=(
            "pa_mpjpe_mm",
            "median",
        ),
        n_rigid_objects=(
            "object",
            "nunique",
        ),
    )
)

frame.to_csv(
    R / "combined_one_row_per_clip_frame.csv",
    index=False,
)


# ============================================================
# MAIN ANALYSIS
#
# For EVERY clip:
#   use ALL available frames
#   Spearman(local Acc, same-time PA-MPJPE)
#
# No threshold.
# No top/bottom 25% selection.
# ============================================================

clip_rows = []

for (task, clip), g in frame.groupby(
    ["task", "clip"],
    sort=False,
):

    g = g.sort_values("frame")

    if len(g) < 5:
        continue

    if (
        g["local_acc_mps2"].nunique() < 3
        or g["pa_mpjpe_mm"].nunique() < 3
    ):
        continue

    rho, p = spearmanr(
        g["local_acc_mps2"],
        g["pa_mpjpe_mm"],
    )

    if not np.isfinite(rho):
        continue

    clip_rows.append({
        "task": task,
        "clip": clip,
        "n_frames": len(g),
        "rho_acc_pa": float(rho),
        "p_acc_pa": float(p),
    })


clip_corr = pd.DataFrame(
    clip_rows
)

clip_corr.to_csv(
    R / "per_clip_allframe_spearman.csv",
    index=False,
)


# ============================================================
# POOLED WITHIN-CLIP RANK CORRELATION
#
# This removes differences such as:
#   "clip A naturally has higher PA than clip B"
#
# and asks only:
#   within the SAME clip,
#   when Acc rank rises, does PA rank rise too?
# ============================================================

def within_clip_rank_corr(x):

    parts = []

    for clip, g in x.groupby(
        "clip",
        sort=False,
    ):

        if len(g) < 5:
            continue

        if (
            g["local_acc_mps2"].nunique() < 3
            or g["pa_mpjpe_mm"].nunique() < 3
        ):
            continue

        q = g.copy()

        q["acc_rank"] = (
            q["local_acc_mps2"]
            .rank(
                method="average",
                pct=True,
            )
        )

        q["pa_rank"] = (
            q["pa_mpjpe_mm"]
            .rank(
                method="average",
                pct=True,
            )
        )

        # Remove clip-specific mean.
        q["acc_rank_c"] = (
            q["acc_rank"]
            - q["acc_rank"].mean()
        )

        q["pa_rank_c"] = (
            q["pa_rank"]
            - q["pa_rank"].mean()
        )

        parts.append(q)

    if not parts:
        return np.nan, np.nan, 0

    z = pd.concat(
        parts,
        ignore_index=True,
    )

    r, p = pearsonr(
        z["acc_rank_c"],
        z["pa_rank_c"],
    )

    return (
        float(r),
        float(p),
        len(z),
    )


# ============================================================
# SUPPLEMENTARY ONLY:
#
# low 25% vs high 25%
#
# This is NOT the criterion and NOT the main test.
# It is only an interpretable effect-size summary.
# ============================================================

quartile_rows = []

for (task, clip), g in frame.groupby(
    ["task", "clip"],
    sort=False,
):

    if len(g) < 8:
        continue

    q25 = g[
        "local_acc_mps2"
    ].quantile(0.25)

    q75 = g[
        "local_acc_mps2"
    ].quantile(0.75)

    lo = g[
        g["local_acc_mps2"] <= q25
    ]

    hi = g[
        g["local_acc_mps2"] >= q75
    ]

    if len(lo) == 0 or len(hi) == 0:
        continue

    lo_pa = float(
        lo["pa_mpjpe_mm"].median()
    )

    hi_pa = float(
        hi["pa_mpjpe_mm"].median()
    )

    quartile_rows.append({
        "task": task,
        "clip": clip,
        "low25_pa_mm": lo_pa,
        "high25_pa_mm": hi_pa,
        "delta_mm": hi_pa - lo_pa,
        "ratio":
            hi_pa / lo_pa
            if lo_pa > 0
            else np.nan,
        "high_greater":
            int(hi_pa > lo_pa),
    })


quart = pd.DataFrame(
    quartile_rows
)

quart.to_csv(
    R / "supplementary_low25_high25.csv",
    index=False,
)


# ============================================================
# Report
# ============================================================

print("=" * 88)
print("FRAME-WISE Acc -> SAME-TIME PA-MPJPE")
print("MAIN = ALL FRAMES, WITHIN EACH CLIP")
print("=" * 88)

print(
    "Raw object/frame rows =",
    len(raw),
)

print(
    "Unique clip/frame rows =",
    len(frame),
)

print(
    "Eligible clips for continuous analysis =",
    len(clip_corr),
)

print()


for task in TASKS + ["ALL"]:

    if task == "ALL":
        f = frame
        c = clip_corr
        q = quart
    else:
        f = frame[
            frame["task"] == task
        ]

        c = clip_corr[
            clip_corr["task"] == task
        ]

        q = quart[
            quart["task"] == task
        ]

    if len(c) == 0:
        continue

    pooled_r, pooled_p, nframe = (
        within_clip_rank_corr(f)
    )

    median_rho = float(
        c["rho_acc_pa"].median()
    )

    positive_pct = float(
        (
            c["rho_acc_pa"] > 0
        ).mean()
        * 100.0
    )

    try:

        w = wilcoxon(
            c["rho_acc_pa"],
            alternative="greater",
        )

        wp = float(w.pvalue)

    except Exception:

        wp = np.nan


    print("-" * 88)

    print(
        f"{task}"
    )

    print(
        f"N clips = {len(c)}"
    )

    print(
        "MAIN continuous result:"
    )

    print(
        f"  median within-clip Spearman rho "
        f"= {median_rho:+.6f}"
    )

    print(
        f"  clips with positive rho "
        f"= {positive_pct:.1f}%"
    )

    print(
        f"  Wilcoxon(rho > 0) "
        f"p={wp:.3e}"
    )

    print(
        f"  pooled within-clip rank correlation "
        f"= {pooled_r:+.6f}, "
        f"p={pooled_p:.3e}, "
        f"frames={nframe}"
    )

    if len(q):

        lo = float(
            q["low25_pa_mm"].median()
        )

        hi = float(
            q["high25_pa_mm"].median()
        )

        ratio = (
            hi / lo
            if lo > 0
            else np.nan
        )

        print(
            "SUPPLEMENTARY quartile summary:"
        )

        print(
            f"  low 25% PA median "
            f"= {lo:.6f} mm"
        )

        print(
            f"  high 25% PA median "
            f"= {hi:.6f} mm"
        )

        print(
            f"  high / low "
            f"= {ratio:.3f}x"
        )

        print(
            f"  clips high > low "
            f"= "
            f"{q['high_greater'].mean()*100:.1f}%"
        )


print()
print("=" * 88)
print("INTERPRETATION RULE")
print("=" * 88)

print(
    "Main evidence is the continuous within-clip relation "
    "using ALL frames."
)

print(
    "The 25% comparison is supplementary only; "
    "it does not define a new threshold or boundary."
)

print()
print(
    "SAVED =",
    R,
)
